        ["-> offset varies with charge: the powder model shape is off, not just a scale."] = "-> lo scarto cambia con la carica: a essere sbagliata è la forma del modello della polvere, non solo la scala.",
        [" Try 'Capture shape-fit sweep (k)' below."] = " Prova 'Cattura sweep stile GRT (Ba + k)' qui sopra.",
        [" Capture a 3rd+ charge, then try the k shape fit."] = " Cattura una terza carica o più, poi prova l'adattamento della forma con k.",
        ["-> capture 2+ charges to tell a scale error from a shape error."] = "-> cattura 2 o più cariche per distinguere un errore di scala da uno di forma.",
        ["suggested Ba for {0}: {1}  (was {2}, x{3})  -- first-order, MV scales as sqrt(Ba)"] = "Ba suggerito per {0}: {1}  (era {2}, x{3})  -- primo ordine, la MV scala come la radice di Ba",
        ["no Ba in the load; apply the offset mentally: GRT runs {0} {1} {2} for this barrel."] = "nel carico non c'è Ba; applica lo scarto a mente: per questa canna GRT va {0} {1} {2}.",
        ["slow"] = "più lento",
