        ["Fit over {0} charge(s) with both baseline and Ba/k-nudged sim MV captured."] = "Adattamento su {0} carica/che, con catturate sia la MV sim di base sia quella con Ba/k variati.",
        ["Verified in GRT at the proposed Ba and k: mean offset {0} m/s (was {1}), RMS {2} m/s (was {3}) -> {4}. {5}"] = "Verificato in GRT con Ba e k proposti: scarto medio {0} m/s (era {1}), RMS {2} m/s (era {3}) -> {4}. {5}",
        ["ACCEPTED"] = "ACCETTATA",
        ["REFUSED"] = "RIFIUTATA",
        ["! NOT verified yet: run 'Verify correction in GRT'. The Ba + k file is written only after GRT's own simulation confirms it."] = "! NON ancora verificata: premi 'Verifica la correzione in GRT'. Il file Ba + k viene scritto solo dopo che la simulazione di GRT stesso lo conferma.",
        ["This is the adjustment GRT's own OBT tool makes (Ba and k scaled by the same factor), so Pmax, BLT and the"] = "È la stessa correzione che fa lo strumento OBT di GRT (Ba e k scalati dello stesso fattore), quindi Pmax, BLT e i",
        ["OBT nodes of the corrected load agree with what GRT's OBT tool would give."] = "nodi OBT del carico corretto coincidono con quelli che darebbe lo strumento OBT di GRT.",
        ["Sebert factor sensitivity"] = "Sensibilità al fattore di Sebert",
        ["This load uses Sebert {0}; simulated in GRT at {1}."] = "Questo carico usa Sebert {0}; simulato in GRT a {1}.",
        ["The chronograph cannot tell the Sebert factor from Ba and k: change it, re-match Ba and k to the same"] = "Il cronografo non distingue il fattore di Sebert da Ba e k: cambialo, riadatta Ba e k alla stessa",
        ["velocity, and the velocity looks identical. It still moves the pressure and the OBT node:"] = "velocità, e la velocità resta identica. Sposta comunque la pressione e il nodo OBT:",
        ["  Sebert {0}: Pmax {1} {2}, BLT {3} ms  -> node charge about {4} {5}"] = "  Sebert {0}: Pmax {1} {2}, BLT {3} ms  -> carica del nodo circa {4} {5}",
        ["BLT moves {0} ms per {1} of charge here, so a Sebert known only to +/-{2} leaves the node's charge uncertain by about +/-{3} {4}"] = "Qui il BLT si sposta di {0} ms per {1} di carica, quindi un Sebert noto solo a +/-{2} lascia la carica del nodo incerta di circa +/-{3} {4}",
        ["(GRT quotes 0.1 to 0.2 gr of node precision.) A measured Pmax, not a velocity, is what constrains the factor."] = "(GRT dichiara una precisione del nodo di 0,1-0,2 gr.) A vincolare il fattore è una Pmax misurata, non una velocità.",
        ["{0}% confidence interval on each string's true mean. \"n needed\" = shots (of that"] = "Intervallo di confidenza al {0}% sulla vera media di ogni serie. \"n servono\" = colpi (con la",
        ["string's own spread) to pin the mean to +/-{0} {1}."] = "dispersione propria della serie) per fissare la media a +/-{0} {1}.",
        ["mean/SD/ES/CI in {0}; SD = sample SD (/(n-1)), the one GRT shows; a chronograph's own (/n) is a little smaller"] = "media/SD/ES/IC in {0}; SD = SD campionaria (/(n-1)), quella che mostra GRT; quella del cronografo (/n) è un po' più piccola",
        [" charge            n   mean    SD    ES  |   {0,2}% CI on mean   | n needed"] = " carica            n   media   SD    ES  |   IC {0,2}% sulla media | n servono",
        ["  * {0}: shot #{1} = {2} {3} flagged (Chauvenet) — {4}"] = "  * {0}: colpo n. {1} = {2} {3} segnalato (Chauvenet) — {4}",
        ["EXCLUDED, not counted above"] = "ESCLUSO, non contato sopra",
