        ["  mean:   {0} vs {1} {2}, diff {3} {2} (p={4}) -> {5}"] = "  media:     {0} contro {1} {2}, diff {3} {2} (p={4}) -> {5}",
        ["different, not chrono noise"] = "diverse, non è rumore del cronografo",
        ["not different — could be chrono noise"] = "non diverse — potrebbe essere rumore del cronografo",
        ["  spread: SD {0} vs {1} {2} (p={3}) -> {4}"] = "  dispersione: SD {0} contro {1} {2} (p={3}) -> {4}",
        ["one load is meaningfully more consistent"] = "un carico è nettamente più regolare",
