        ["{0} in {1}, MV/SD/ES in {2}, dist in {3}, POI-Y/grpMR/vert in MOA"] = "{0} in {1}, MV/SD/ES in {2}, dist in {3}, POI-Y/grpMR/vert in MOA",
        ["{0,7}  n   MV      SD    ES   | dist  POI-Y   grpMR  vert"] = "{0,7}  n   MV      SD    ES   | dist  POI-Y   grpMR  vert",
