        ["Recommended node (weighted)"] = "Nodo consigliato (ponderato)",
        ["Method: MOA target coordinates from OnTarget."] = "Metodo: coordinate MOA del bersaglio da OnTarget.",
        ["Method: MOA target coordinates from OnTarget, velocities from Athlon Rangecraft."] = "Metodo: coordinate MOA del bersaglio da OnTarget, velocità da Athlon Rangecraft.",
        ["SD is the sample SD (n-1), as GRT shows it. Confirm any node with a fresh confirmation group before committing."] = "La SD è la SD campionaria (n-1), come la mostra GRT. Conferma qualsiasi nodo con un nuovo gruppo di conferma prima di adottarlo.",
        ["n/a"] = "n.d.",
        ["{0}: {1}-{2} {3}  (center {4})  -- {5}"] = "{0}: {1}-{2} {3}  (centro {4})  -- {5}",
        ["need at least 2 usable strings at different temperatures"] = "servono almeno 2 serie utilizzabili a temperature diverse",
        ["normal point is {0}, not {1} — used its MV as the reference"] = "il punto normale è a {0}, non a {1} — ho usato la sua MV come riferimento",
        ["no string near {0} — extrapolated MV there ≈ {1} from a linear fit"] = "nessuna serie vicino a {0} — la MV estrapolata lì è ≈ {1} da un adattamento lineare",
