        ["hot side : {0} {1}"] = "lato caldo : {0} {1}",
        ["tcc = {0}   (GRT cold coefficient, ΔBa per °C below 21°C -- GRT's own definition)"] = "tcc = {0}   (coefficiente freddo di GRT, ΔBa per °C sotto i 21°C -- definizione propria di GRT)",
        ["tch = {0}   (GRT hot coefficient, ΔBa per °C above 21°C -- GRT's own definition)"] = "tch = {0}   (coefficiente caldo di GRT, ΔBa per °C sopra i 21°C -- definizione propria di GRT)",
        ["no coefficients fitted — see notes."] = "nessun coefficiente calcolato — vedi le note.",
        ["Method: Ba(T) ≈ Ba_normal·(MV(T)/MV_21)² per GRT formalism (formalism.txt). First-order."] = "Metodo: Ba(T) ≈ Ba_normale·(MV(T)/MV_21)² secondo il formalismo di GRT (formalism.txt). Primo ordine.",
        ["Best with 3 strings: cold (~{0}), normal ({1}), hot (~{2}), same charge & barrel."] = "Meglio con 3 serie: fredda (~{0}), normale ({1}), calda (~{2}), stessa carica e stessa canna.",
        ["CBTO is less than case length - the ogive would sit below the case mouth. Re-check CBTO and case length."] = "CBTO è minore della lunghezza del bossolo - l'ogiva starebbe sotto la bocca del bossolo. Ricontrolla CBTO e lunghezza del bossolo.",
        ["Seating depth came out <= 0 - the bullet base would be at or above the case mouth. Re-check BBTO."] = "La profondità di seduta è risultata <= 0 - la base del proiettile sarebbe alla bocca del bossolo o sopra. Ricontrolla BBTO.",
        ["Seating depth exceeds the case length - not physically possible. Re-check the inputs."] = "La profondità di seduta supera la lunghezza del bossolo - fisicamente impossibile. Ricontrolla i dati.",
        ["Seating depth under ~3 mm is very shallow - little bearing surface in the neck for grip/alignment."] = "Una profondità di seduta sotto ~3 mm è molto bassa - poca superficie d'appoggio nel collo per presa e allineamento.",
        ["Seating depth over 0.5 in (12.7 mm) is unusually deep for most cartridges - worth double-checking."] = "Una profondità di seduta oltre 0,5 in (12,7 mm) è insolitamente profonda per la maggior parte dei bossoli - vale la pena ricontrollare.",
        ["no measured charges found in the load's Measurements"] = "nessuna carica misurata trovata nelle Misurazioni del carico",
        ["loaded {0} measured charge(s) from '{1}'  Ba={2}"] = "caricate {0} cariche misurate da '{1}'  Ba={2}",
        ["Get_TabResults returned no muzzle velocity — compute a result in GRT first."] = "Get_TabResults non ha restituito la velocità alla volata — calcola prima un risultato in GRT.",
        ["captured sim MV {0} for {1} (GRT's current charge)  Pmax {2} {3}"] = "MV sim catturata {0} per {1} (carica attuale di GRT)  Pmax {2} {3}",
