        ["{0} gr @ Ba,k +{1} -> sim {2} m/s"] = "{0} gr @ Ba,k +{1} -> sim {2} m/s",
        ["{0} gr @ Ba,k +{1} -> no sim MV (skipped)"] = "{0} gr @ Ba,k +{1} -> nessuna MV sim (saltata)",
