        ["ERROR:"] = "ERRORE:",
        ["Barrel Calibration"] = "Calibrazione canna",
        ["Velocity drifts along the string: {0} {1} per shot ± {2} (p={3}), {4} {1} from the first shot to the last."] = "La velocità deriva lungo la serie: {0} {1} per colpo ± {2} (p={3}), {4} {1} dal primo all'ultimo colpo.",
        ["Taking that straight drift out leaves an SD of {0} {1} instead of {2}."] = "Togliendo quella deriva lineare resta una SD di {0} {1} invece di {2}.",
        ["A barrel that heats, powder warming in the sun and fouling all look like this, and the order of the shots cannot tell them apart: a longer pause between shots, or a barrel-temperature reading per shot, separates heating from the rest."] = "Una canna che si scalda, la polvere che si scalda al sole e lo sporco si vedono tutti così, e l'ordine dei colpi non li distingue: una pausa più lunga tra i colpi, o una lettura della temperatura della canna a ogni colpo, separa il riscaldamento dal resto.",
        ["No drift along the string: {0} {1} per shot ± {2} (p={3})."] = "Nessuna deriva lungo la serie: {0} {1} per colpo ± {2} (p={3}).",
        ["Pause between shots: median {0} s (from {1} to {2} s)."] = "Pausa tra i colpi: mediana {0} s (da {1} a {2} s).",
        ["Velocity against the pause before the shot: r={0} (p={1}, {2} shots)."] = "Velocità contro la pausa prima del colpo: r={0} (p={1}, {2} colpi).",
        ["Shots fired after a longer pause were faster: the rate of fire matters, as it does when the barrel is hot."] = "I colpi sparati dopo una pausa più lunga erano più veloci: conta il ritmo di tiro, come succede con la canna calda.",
        ["Shots fired after a shorter pause were faster: the rate of fire matters, as it does when the barrel is hot."] = "I colpi sparati dopo una pausa più breve erano più veloci: conta il ritmo di tiro, come succede con la canna calda.",
        ["The drift does not depend on how quickly the shots were fired: it follows the string, not the rate of fire."] = "La deriva non dipende da quanto in fretta sono stati sparati i colpi: segue la serie, non il ritmo di tiro.",
        ["🌀  Gyroscopic stability (twist)"] = "🌀  Stabilità giroscopica (torsione)",
