        ["Velocity factor {0}, air factor {1}. Twist {2} calibres per turn, bullet {3} calibres long."] = "Fattore di velocità {0}, fattore dell'aria {1}. Torsione {2} calibri per giro, proiettile lungo {3} calibri.",
        ["Slowest twist that gives Sg 1.5 in these conditions: {0}; Sg 1.4: {1}."] = "La torsione più lenta che dà Sg 1,5 in queste condizioni: {0}; Sg 1,4: {1}.",
        ["Greenhill's older rule, as a cross-check only: {0}."] = "La regola più vecchia di Greenhill, solo come controllo: {0}.",
        ["Sg for other air temperatures (same bullet, velocity and altitude):"] = "Sg con altre temperature dell'aria (stesso proiettile, velocità e quota):",
