        ["powder lot"] = "lotto di polvere",
        ["primer lot"] = "lotto di inneschi",
        ["seating depth"] = "profondità di seduta",
        ["NOT EVALUATED (missing data, not a clean bill of health)"] = "NON VALUTATO (dati mancanti, non un via libera)",
        ["Everything above is about THIS load's own history. With few outings a verdict can be wrong either way; it firms up as the outings add up."] = "Tutto quanto sopra riguarda la storia di QUESTO carico. Con poche uscite un verdetto può sbagliare in entrambi i sensi; si consolida man mano che le uscite aumentano.",
        ["outside what is usual for it"] = "fuori da ciò che è normale per lui",
        ["on the edge of what is usual for it"] = "al limite di ciò che è normale per lui",
        ["normal for it"] = "normale per lui",
        ["clearly wider than usual"] = "nettamente più ampia del solito",
        ["wider than usual, to watch"] = "più ampia del solito, da tenere d'occhio",
        ["as usual"] = "come al solito",
        ["Temperature effect: not evaluated, it needs at least {0} sessions with a temperature written down, at least {1} apart (there are {2}, {3} apart)."] = "Effetto della temperatura: non valutato, servono almeno {0} uscite con una temperatura scritta, distanti almeno {1} (ce ne sono {2}, distanti {3}).",
        ["Drift over time: not evaluated, it needs at least {0} sessions at least {1} days apart (there are {2}, {3} days apart)."] = "Deriva nel tempo: non valutata, servono almeno {0} uscite distanti almeno {1} giorni (ce ne sono {2}, distanti {3} giorni).",
        ["Latest outing against the earlier ones: not evaluated, it needs at least {0} earlier sessions of {1} shots or more (there are {2})."] = "Ultima uscita contro le precedenti: non valutata, servono almeno {0} uscite precedenti di {1} colpi o più (ce ne sono {2}).",
        // Match lots and training lots
        ["Imitates"] = "Imita",
        ["Imitates the match lot:"] = "Imita il lotto di gara:",
        ["Compare with the match lot"] = "Confronta con il lotto di gara",
        ["Say which match lot this training lot imitates first."] = "Prima di tutto di' quale lotto di gara imita questo lotto di allenamento.",
        ["The model learned from {0} shots: {1} fired from training lots, {2} from match lots."] = "Il modello ha imparato da {0} colpi: {1} sparati da lotti di allenamento, {2} da lotti di gara.",
        ["New training lot…"] = "Nuovo lotto di allenamento…",
        ["New match lot…"] = "Nuovo lotto di gara…",
        ["Make it a match lot"] = "Rendilo un lotto di gara",
        ["Make it a training lot"] = "Rendilo un lotto di allenamento",
        ["New training lot"] = "Nuovo lotto di allenamento",
        ["New match lot"] = "Nuovo lotto di gara",
        ["Nothing to compare yet: the model has no proven measure, or the cartridges of the match lot do not carry it."] = "Ancora niente da confrontare: il modello non ha nessuna misura dimostrata, oppure le cartucce del lotto di gara non la hanno.",
        ["{0}: the model saw values from {1} to {2}; {3} of the {4} cartridges of the match lot are inside ({5} to {6})."] = "{0}: il modello ha visto valori da {1} a {2}; {3} delle {4} cartucce del lotto di gara sono dentro ({5} … {6}).",
        ["The training cartridges average {0}, the match lot {1}: {2} SD of the training lot apart."] = "Le cartucce di allenamento hanno in media {0}, il lotto di gara {1}: {2} SD del lotto di allenamento di distanza.",
        ["The match lot stays inside what the model has seen: the prediction for it is an interpolation and can be used."] = "Il lotto di gara resta dentro quello che il modello ha visto: la previsione è un'interpolazione e si può usare.",
        ["Part of the match lot lies outside what the model has seen, or the two lots are not alike: use the prediction with care, and shoot training cartridges that cover the missing values."] = "Una parte del lotto di gara sta fuori da quello che il modello ha visto, oppure i due lotti non si assomigliano: usa la previsione con cautela e spara cartucce di allenamento che coprano i valori mancanti.",
        ["Much of the match lot lies outside what the model has seen: for those cartridges the prediction is an extrapolation and cannot be trusted. Make training cartridges that cover the values of the match lot."] = "Gran parte del lotto di gara sta fuori da quello che il modello ha visto: per quelle cartucce la previsione è un'estrapolazione e non ci si può fidare. Prepara cartucce di allenamento che coprano i valori del lotto di gara.",
        ["Match lots"] = "Lotti di gara",
        ["The lot \"{0}\" is the match lot, kept for the match. Link these shots to it only if they were fired in the match or in a check of this lot, not in training. Link them?"] = "Il lotto \"{0}\" è il lotto di gara, tenuto per la gara. Collega questi colpi solo se sono stati sparati in gara o in una verifica di questo lotto, non in allenamento. Li collego?",
        ["training"] = "allenamento",
        ["match"] = "gara",
        ["The match lot is kept for the match: do not shoot it in training. Make other cartridges, in the Training tab, to learn and to try things out."] = "Il lotto di gara è tenuto per la gara: non sparalo in allenamento. Prepara altre cartucce, nella scheda Allenamento, per imparare e provare.",
        ["Training lots are other cartridges than the match's: shoot them to teach the model what moves the velocity, to try a plan and to check a prediction. They are never the lot you take to the match."] = "I lotti di allenamento sono altre cartucce rispetto a quelle della gara: sparale per insegnare al modello che cosa muove la velocità, per provare un piano e per verificare una previsione. Non sono mai il lotto che porti in gara.",
        // The match reading: one shot for each target, taken apart into cartridge, settings, wind and shooting
        ["The velocity of the cartridges moves the shots"] = "La velocità delle cartucce sposta i colpi",
        ["Once the distance is taken into account, the velocity explains {0} % of the vertical error that is left: the shots with a higher velocity go higher, {1} times what the drop without air predicts (the probability that it is chance is {2} %). The spread of the velocity ({3} m/s, extreme spread {4} m/s) alone opens the group by {5} MOA at {6} m."] = "Tenuto conto della distanza, la velocità spiega il {0} % dell'errore verticale che resta: i colpi con più velocità vanno più in alto, {1} volte quanto prevede la caduta senza aria (probabilità che sia un caso: {2} %). La sola dispersione della velocità ({3} m/s, escursione {4} m/s) apre il gruppo di {5} MOA a {6} m.",
        ["Reduce the spread of the velocity: weigh every charge, sort the cases by weight and volume, keep the same neck tension and the same primers, and check a string of the same lot on the chronograph before the match."] = "Riduci la dispersione della velocità: pesa ogni carica, seleziona i bossoli per peso e volume, tieni la stessa tensione del collo e gli stessi inneschi, e controlla al cronografo una serie dello stesso lotto prima della gara.",
        ["The velocity of the cartridges does not move the shots: its spread ({0} m/s) would open the group by only {1} MOA at {2} m."] = "La velocità delle cartucce non sposta i colpi: la sua dispersione ({0} m/s) aprirebbe il gruppo solo di {1} MOA a {2} m.",
        ["Cartridges with a velocity out of line"] = "Cartucce con velocità fuori linea",
        ["Cartridges whose velocity is far from all the others:"] = "Cartucce con la velocità lontana da tutte le altre:",
        ["(to be confirmed) = the evidence is weak, between 1 % and 5 % of chance: it counts only if the next match shows it again."] = "(da confermare) = la prova è debole, tra l'1 % e il 5 % di caso: conta solo se la prossima gara la mostra ancora.",
        ["{0} (to be confirmed)"] = "{0} (da confermare)",
        ["Shot {0} ({1}, {2} m): {3} m/s, {4} m/s from the average; at that distance it moves the shot {5} MOA {6}"] = "Colpo {0} ({1}, {2} m): {3} m/s, {4} m/s dalla media; a quella distanza sposta il colpo di {5} MOA {6}",
        ["A cartridge out of line: look at the others of the same lot (charge, primer seating, case) and mark the cartridges so that you know which one it was."] = "Una cartuccia fuori linea: guarda le altre dello stesso lotto (carica, sede dell'innesco, bossolo) e segna le cartucce per sapere quale era.",
        ["Cartridges of different lots shoot to different points"] = "Le cartucce di lotti diversi colpiscono in punti diversi",
        ["Not explained by the velocity: {0} (vertical: the probability that it is chance is {1} %, sideways: {2} %)."] = "Non spiegato dalla velocità: {0} (verticale: probabilità che sia un caso {1} %, di lato: {2} %).",
        ["{0}: {1} MOA {2}, {3} MOA {4}"] = "{0}: {1} MOA {2}, {3} MOA {4}",
        ["Zero the rifle for each lot, or find what changes from one lot to the other: lot of powder, of primers, of bullets, seating depth, case brand."] = "Azzera il fucile per ogni lotto, oppure trova che cosa cambia da un lotto all'altro: lotto di polvere, di inneschi, di ogive, profondità di seduta, marca dei bossoli.",
        ["The lots shoot to the same point."] = "I lotti colpiscono nello stesso punto.",
        ["With {0} clicks: {1}."] = "Con click da {0}: {1}.",
        ["On average, at the middle distance of the targets ({0} m), the shots are {1} MOA to the {2} and {3} MOA {4} of the point of aim (the probability that it is chance is {5} %)."] = "In media, alla distanza di mezzo dei bersagli ({0} m), i colpi sono {1} MOA a {2} e {3} MOA {4} il punto di mira (probabilità che sia un caso: {5} %).",
        ["The zero of the sight is right: on average the shots are {0} / {1} MOA from the point of aim, which cannot be told from nothing."] = "Lo zero dell'ottica è giusto: in media i colpi sono a {0} / {1} MOA dal punto di mira, che non si distingue da zero.",
        ["The elevation does not follow the distance"] = "L'alzo non segue la distanza",
        ["The farther the target, the {0} the shots land: {1} MOA more for every 100 m ({2} MOA between {3} m and {4} m; the probability that it is chance is {5} %)."] = "Più il bersaglio è lontano, più i colpi arrivano {0}: {1} MOA in più ogni 100 m ({2} MOA tra {3} m e {4} m; probabilità che sia un caso: {5} %).",
        ["higher"] = "in alto",
        ["lower"] = "in basso",
        ["The elevations do not suit the rifle: check the muzzle velocity and the ballistic coefficient used in the ballistic program, the distance of the zero, the height of the scope over the bore, the air (temperature and pressure) and that a click is really worth what it says (dial 10 MOA up and check on a target)."] = "Gli alzi non si adattano al fucile: controlla la velocità alla volata e il coefficiente balistico usati nel programma balistico, la distanza dello zero, l'altezza dell'ottica sulla canna, l'aria (temperatura e pressione) e che un click valga davvero quanto dice (gira 10 MOA in alto e controlla su un bersaglio).",
        ["The elevation follows the distance: the vertical error does not change with it."] = "L'alzo segue la distanza: l'errore verticale non cambia con essa.",
        ["The sideways error grows with the distance"] = "L'errore di lato cresce con la distanza",
        ["The farther the target, the more the shots go to the {0}: {1} MOA more for every 100 m ({2} MOA between {3} m and {4} m; the probability that it is chance is {5} %)."] = "Più il bersaglio è lontano, più i colpi vanno a {0}: {1} MOA in più ogni 100 m ({2} MOA tra {3} m e {4} m; probabilità che sia un caso: {5} %).",
        ["Typical causes: scope not level (the error grows with the elevation dialled, so with the distance: check the reticle with a level), windage zero not right at long range, spin drift not applied, a steady wind from one side all the match."] = "Cause tipiche: ottica non in bolla (l'errore cresce con l'alzo impostato, quindi con la distanza: controlla il reticolo con una livella), zero della deriva non giusto a lunga distanza, deriva giroscopica non applicata, un vento costante da un lato per tutta la gara.",
        ["The wind is not corrected enough"] = "Il vento non è corretto abbastanza",
        ["The wind is over-corrected"] = "Il vento è corretto troppo",
        ["The shots {0} the wind: {1} MOA for every 1 m/s of across wind at 100 m of distance (the probability that it is chance is {2} %)."] = "I colpi {0} il vento: {1} MOA per ogni 1 m/s di vento laterale ogni 100 m di distanza (probabilità che sia un caso: {2} %).",
        ["follow"] = "seguono",
        ["go against"] = "vanno contro",
        ["You hold less than the wind needs: take the holds from a wind table or a ballistic program for the speed and the direction, and read the wind along the whole way to the target (the flags near the target count more than those at the firing line)."] = "Tieni meno di quanto serve al vento: prendi le correzioni da una tabella del vento o da un programma balistico per velocità e direzione, e leggi il vento lungo tutto il percorso fino al bersaglio (le bandierine vicino al bersaglio contano più di quelle alla linea di tiro).",
        ["You hold more than the wind needs: you read more wind than there is, or you hold for the wind of the firing line; check the holds with a wind table and read the wind along the whole way to the target."] = "Tieni più di quanto serve al vento: leggi più vento di quello che c'è, o correggi per il vento della linea di tiro; controlla le correzioni con una tabella del vento e leggi il vento lungo tutto il percorso fino al bersaglio.",
        ["The wind is corrected well: the shots do not follow it."] = "Il vento è corretto bene: i colpi non lo seguono.",
        ["The position changes the point of impact"] = "La posizione cambia il punto d'impatto",
        ["{0} (vertical: the probability that it is chance is {1} %, sideways: {2} %)."] = "{0} (verticale: probabilità che sia un caso {1} %, di lato: {2} %).",
        ["The rifle is not held the same way in every position, so the zero moves with it: learn the shift of each position and check the support (sling, bag, bipod loading, cheek)."] = "Il fucile non è tenuto allo stesso modo in ogni posizione, quindi lo zero si sposta con essa: impara lo spostamento di ogni posizione e controlla l'appoggio (cinghia, sacchetto, carico del bipiede, guancia).",
        ["The positions shoot to the same point."] = "Le posizioni colpiscono nello stesso punto.",
        ["The wind was not recorded, so it cannot be told apart from the shooting: write the wind for each shot next time."] = "Il vento non è stato registrato, quindi non si distingue dal tiro: la prossima volta scrivi il vento per ogni colpo.",
        ["After the cartridges, the settings and the wind are taken out, the shots spread {0} MOA sideways and {1} MOA in height (the probability that it is chance is {2} %)."] = "Tolti cartucce, impostazioni e vento, i colpi si spargono {0} MOA di lato e {1} MOA in altezza (probabilità che sia un caso: {2} %).",
        ["After the cartridges, the settings and the wind are taken out, the shots spread {0} MOA in height and {1} MOA sideways (the probability that it is chance is {2} %)."] = "Tolti cartucce, impostazioni e vento, i colpi si spargono {0} MOA in altezza e {1} MOA di lato (probabilità che sia un caso: {2} %).",
        ["Sideways ({0} MOA) and vertical ({1} MOA) are alike: neither direction is worse than the other."] = "Lato ({0} MOA) e verticale ({1} MOA) sono simili: nessuna direzione è peggiore dell'altra.",
        ["Shots out of the shooter's normal scatter"] = "Colpi fuori dalla normale dispersione del tiratore",
        ["Shots further from the aim than {0} times the normal scatter, once the cartridge, the settings and the wind are taken out:"] = "Colpi più lontani dalla mira di {0} volte la dispersione normale, tolti cartuccia, impostazioni e vento:",
        ["Shot {0} ({1}, {2} m): {3} MOA {4} and {5} MOA {6} more than the others would explain"] = "Colpo {0} ({1}, {2} m): {3} MOA {4} e {5} MOA {6} più di quanto spiegherebbero gli altri",
        ["A badly fired shot (pulled, a flinch, a changed position) or a gust of wind that was not seen: write on the target at once what you felt, so that next time you know which of the two it was."] = "Un colpo tirato male (strappato, un sobbalzo, una posizione cambiata) o una raffica di vento non vista: segna subito sul cartellino che cosa hai sentito, così la volta dopo sai quale dei due era.",
        ["The shot moves {0} during the match"] = "Il colpo si sposta {0} durante la gara",
        ["From the first shot to the last the point of impact moves {0} MOA {1} (the probability that it is chance is {2} %)."] = "Dal primo all'ultimo colpo il punto d'impatto si sposta di {0} MOA {1} (probabilità che sia un caso: {2} %).",
        ["The more time passes from the shot before (the move to the next target is included), the further the shot goes from where it should (Spearman {0}, the probability that it is chance is {1} %). On average {2} s between one shot and the next."] = "Più tempo passa dal colpo prima (compreso lo spostamento al bersaglio successivo), più il colpo va lontano da dove dovrebbe (Spearman {0}, probabilità che sia un caso {1} %). In media {2} s tra un colpo e l'altro.",
        ["Shots fired soon after the previous one go further from where they should (Spearman {0}, the probability that it is chance is {1} %)."] = "I colpi sparati poco dopo il precedente vanno più lontano da dove dovrebbero (Spearman {0}, probabilità che sia un caso {1} %).",
        ["A bad shot drags the next one"] = "Un colpo cattivo trascina il successivo",
        ["The shot after a bad shot is also worse (Spearman {0}, the probability that it is chance is {1} %)."] = "Anche il colpo dopo un colpo cattivo è peggiore (Spearman {0}, probabilità che sia un caso {1} %).",
        ["After a bad shot do not rush: come off, breathe, find the cause and write it down, then put yourself back in position before the next target."] = "Dopo un colpo cattivo non avere fretta: stacca, respira, trova la causa e scrivila, poi rimettiti in posizione prima del bersaglio successivo.",
        ["A bad shot does not drag the next one."] = "Un colpo cattivo non trascina il successivo.",
        ["Shot {0} ({1}, {2} m)"] = "Colpo {0} ({1}, {2} m)",
        ["{0}: the cartridge. Its velocity ({1} m/s from the average) moves the shot {2} MOA {3}."] = "{0}: la cartuccia. La sua velocità ({1} m/s dalla media) sposta il colpo di {2} MOA {3}.",
        ["{0}: the settings. The zero and the elevation or windage at this distance leave the shot {1} MOA {2} and {3} MOA {4}."] = "{0}: le impostazioni. Lo zero e l'alzo o la deriva a questa distanza lasciano il colpo a {1} MOA {2} e {3} MOA {4}.",
        ["{0}: the wind. {1} m/s across was {2}: {3} MOA {4}."] = "{0}: il vento. {1} m/s laterali sono stati {2}: {3} MOA {4}.",
        ["not corrected enough"] = "corretti poco",
        ["over-corrected"] = "corretti troppo",
        ["{0}: the shooting. {1} times the normal scatter once the cartridge, the settings and the wind are taken out."] = "{0}: il tiro. {1} volte la dispersione normale tolti cartuccia, impostazioni e vento.",
        ["{0} shots on {1} targets, from {2} m to {3} m. The shots are on average {4} MOA from the point of aim of their own target."] = "{0} colpi su {1} bersagli, da {2} m a {3} m. I colpi sono in media a {4} MOA dal punto di mira del proprio bersaglio.",
        ["Each error is made of four parts; on average they are worth (MOA): cartridges {0}, settings {1}, wind not corrected {2}, shooting {3}. Below {4} MOA (half a click) a part cannot be corrected on the scope."] = "Ogni errore è fatto di quattro parti; in media valgono (MOA): cartucce {0}, impostazioni {1}, vento non corretto {2}, tiro {3}. Sotto {4} MOA (mezzo click) una parte non si può correggere sull'ottica.",
        ["Nothing in this match points to a problem of the cartridges, of the settings or of the shooter. That is not proof that there is none: with few shots only large effects show."] = "Niente in questa gara indica un problema delle cartucce, delle impostazioni o del tiratore. Non è una prova che non ce ne siano: con pochi colpi si vedono solo gli effetti grandi.",
        ["What points to a problem ({0}):"] = "Cosa indica un problema ({0}):",
        ["Shot by shot (errors in MOA from the point of aim: + right and up; then the four parts):"] = "Colpo per colpo (errori in MOA dal punto di mira: + destra e alto; poi le quattro parti):",
        ["m"] = "m",
        ["Right"] = "Destra",
        ["Up"] = "Alto",
        ["Cartridge"] = "Cartuccia",
        ["Settings"] = "Impostazioni",
        ["Shooting"] = "Tiro",
        ["Main cause"] = "Causa principale",
        ["What is behind the shots that stand out:"] = "Cosa c'è dietro i colpi che si notano:",
        ["Each reading is a test on these shots, with the probability that it is chance written beside it. In a match the shots are few and every one has its own distance and wind: a problem that is not found may still be there, and one that is found should be confirmed in the next match. The parts are separated by the numbers of this match only; the velocity part uses the drop without air."] = "Ogni lettura è un test su questi colpi, con accanto la probabilità che sia un caso. In gara i colpi sono pochi e ognuno ha la sua distanza e il suo vento: un problema che non si trova può esserci lo stesso, e uno che si trova va confermato nella prossima gara. Le parti sono separate solo con i numeri di questa gara; la parte della velocità usa la caduta senza aria.",
        ["The cartridges"] = "Le cartucce",
        ["The settings of the rifle and the scope"] = "Le impostazioni del fucile e dell'ottica",
        ["The conditions (wind)"] = "Le condizioni (vento)",
        ["The shooter"] = "Il tiratore",
        ["cartridge"] = "cartuccia",
        ["settings"] = "impostazioni",
        ["wind"] = "vento",
        ["shooting"] = "tiro",
        ["Line {0}: a value cannot be read (distance, v=, w=, pos=, lot=, name= or the time)."] = "Riga {0}: un valore non si legge (distanza, v=, w=, pos=, lot=, name= o l'ora).",
        ["{0}: no distance, {1} m is used."] = "{0}: nessuna distanza, si usano {1} m.",
        ["Some groups have no point of aim marked: a match is read from the point of aim of each target, so this reading is not reliable."] = "Alcune rosate non hanno il punto di mira segnato: una gara si legge dal punto di mira di ogni bersaglio, quindi questa lettura non è affidabile.",
        ["Match: one shot for each target, several targets"] = "Gara: un colpo per ogni bersaglio, più bersagli",
        ["{0} targets of the archive, {1} shots."] = "{0} bersagli dell'archivio, {1} colpi.",
        ["One line for each shot, in the order fired: x y distance, with x to the right and y UP in millimetres on that target from its own point of aim, and metres. Then, if you have them: v=831 (velocity m/s), w=+3 (across wind m/s, + when it pushes the bullet to the right), pos=prone (position), lot=A (cartridge lot), name=T4 (the target) and the time (10:14:02). The distance may be left out when it is the one in the window. A line that begins with # is a comment."] = "Una riga per ogni colpo, nell'ordine in cui è stato sparato: x y distanza, con x verso destra e y verso l'ALTO in millimetri su quel bersaglio dal suo punto di mira, e metri. Poi, se li hai: v=831 (velocità m/s), w=+3 (vento laterale m/s, + quando spinge l'ogiva a destra), pos=prone (posizione), lot=A (lotto delle cartucce), name=T4 (il bersaglio) e l'ora (10:14:02). La distanza si può omettere quando è quella nella finestra. Una riga che comincia con # è un commento.",
        ["Typed: {0} shots on {1} targets."] = "Scritti: {0} colpi su {1} bersagli.",
        ["Distance when not typed (m):"] = "Distanza se non scritta (m):",
        ["A match: one shot for each target, targets at different distances, in different wind or position. Each shot is turned into MOA from the point of aim of its own target and taken apart into the cartridge, the settings, the wind and the shooting; every shot is named for what weighs most on it, and the whole match is read for problems of the cartridges, the settings, the conditions or the shooter. At least 6 shots are needed. Each group of the archive is one target."] = "Una gara: un colpo per ogni bersaglio, bersagli a distanze diverse, con vento o posizione diversi. Ogni colpo è portato in MOA dal punto di mira del proprio bersaglio e scomposto in cartuccia, impostazioni, vento e tiro; ogni colpo prende il nome di ciò che pesa di più su di lui, e tutta la gara è letta per problemi delle cartucce, delle impostazioni, delle condizioni o del tiratore. Servono almeno 6 colpi. Ogni rosata dell'archivio è un bersaglio.",
        // GroupReadingForm and the shooter-error reading: the pattern of the shots on the target
        ["{0} {1} mm {2} / {3} mm {4}"] = "{0}: {1} mm a {2} / {3} mm {4}",
        ["right"] = "destra",
        ["high"] = "in alto",
        ["low"] = "in basso",
        ["above"] = "sopra",
        ["below"] = "sotto",
        ["The centre of all the shots is {0} mm to the {1} and {2} mm {3} of the point of aim ({4} and {5} MOA at {6} m). It is not chance: the probability that it is chance is {7} %. Series by series (mm): {8}."] = "Il centro di tutti i colpi è {0} mm a {1} e {2} mm {3} il punto di mira ({4} e {5} MOA a {6} m). Non è un caso: la probabilità che lo sia è {7} %. Serie per serie (mm): {8}.",
        ["With {0} clicks ({1} mm at {2} m): {3}."] = "Con click da {0} ({1} mm a {2} m): {3}.",
        ["The zero of the sight is not right"] = "Lo zero dell'ottica non è giusto",
        ["After the proving shots look at where the CENTRE of the group is, not the single shot: if it is more than half a click off, correct the sight before the series (and again before each return, because the point of impact moves with the heat of the barrel)."] = "Dopo i colpi di prova guarda dove sta il CENTRO del gruppo, non il colpo singolo: se è fuori di più di mezzo click, correggi l'ottica prima della serie (e di nuovo prima di ogni rientro, perché il punto d'impatto si sposta con il caldo della canna).",
        ["The zero of the sight is right: the centre of the shots ({0} / {1} mm) cannot be told from the point of aim."] = "Lo zero dell'ottica è giusto: il centro dei colpi ({0} / {1} mm) non si distingue dal punto di mira.",
        ["Sideways error bigger than the vertical one"] = "Errore di lato più grande del verticale",
        ["Around the centre of the group the shots spread {0} mm sideways and {1} mm in height (the part due to velocity taken out). At {2} m the cartridges do not move the shot sideways, so the difference comes from the shooting or the wind (the probability that it is chance is {3} %)."] = "Attorno al centro del gruppo i colpi si spargono {0} mm di lato e {1} mm in altezza (tolta la parte dovuta alla velocità). A {2} m le cartucce non spostano il colpo di lato, quindi la differenza viene dal tiro o dal vento (probabilità che sia un caso: {3} %).",
        ["Vertical {0} mm against {1} mm sideways."] = "Verticale {0} mm contro {1} mm di lato.",
        ["Vertical error bigger than the sideways one"] = "Errore verticale più grande di quello di lato",
        ["Around the centre of the group the shots spread {0} mm in height (the part due to velocity taken out) and {1} mm sideways (the probability that it is chance is {2} %)."] = "Attorno al centro del gruppo i colpi si spargono {0} mm in altezza (tolta la parte dovuta alla velocità) e {1} mm di lato (probabilità che sia un caso: {2} %).",
        ["Sideways ({0} mm) and vertical ({1} mm) are alike: neither direction is worse than the other."] = "Lato ({0} mm) e verticale ({1} mm) sono simili: nessuna direzione è peggiore dell'altra.",
        ["the velocity ({0} m/s) explains {1} % of it"] = "la velocità ({0} m/s) ne spiega il {1} %",
        ["velocity not measured"] = "velocità non misurata",
        ["{0}, shot {1}: {2} mm {3} and {4} mm {5} of the group; {6}"] = "{0}, colpo {1}: {2} mm {3} e {4} mm {5} rispetto al gruppo; {6}",
        ["to the right"] = "a destra",
        ["to the left"] = "a sinistra",
        ["Shots out of the group"] = "Colpi fuori gruppo",
        ["Shots further from the centre of their own series than {0} times the normal spread (by chance fewer than half a shot would be):"] = "Colpi lontani dal centro della propria serie più di {0} volte la dispersione normale (per caso ne capiterebbe meno di mezzo):",
        ["If the velocity does not explain it, it is a badly fired shot or a gust of wind: write on the target at once what you felt (a \"pulled\" shot, a movement, wind) so that next time you know which of the two it was."] = "Se la velocità non lo spiega, è un colpo tirato male o una raffica di vento: segna subito sul cartellino che cosa hai sentito (colpo \"strappato\", movimento, vento) così la volta dopo sai quale dei due era.",
        ["sideways"] = "di lato",
        ["in height"] = "in altezza",
        ["upwards"] = "verso l'alto",
        ["downwards"] = "verso il basso",
        ["The shot moves {0} during the series"] = "Il colpo si sposta {0} durante la serie",
        ["Shot after shot the point of impact moves {0} mm {1} (the probability that it is chance is {2} %)."] = "Colpo dopo colpo il punto d'impatto si muove di {0} mm {1} (probabilità che sia un caso: {2} %).",
        ["A position that settles or tires during the series, a bipod or a bag that slips, light or mirage that change: check the position again in the middle of the series."] = "Posizione che si assesta o si stanca durante la serie, bipiede o sacchetto che scivolano, luce o miraggio che cambiano: ricontrolla la posizione a metà serie.",
        ["Shots held a long time go worse"] = "I colpi tenuti a lungo vanno peggio",
        ["The more time passes from the shot before, the further the shot goes from the group (Spearman {0}, the probability that it is chance is {1} %). On average {2} s between one shot and the next."] = "Più tempo passa dal colpo prima, più il colpo va lontano dal gruppo (Spearman {0}, probabilità che sia un caso {1} %). In media {2} s tra un colpo e l'altro.",
        ["If the shot does not go within a few seconds of the aim being steady, come off, breathe and start again."] = "Se il colpo non parte entro pochi secondi da quando la mira è ferma, stacca, respira e riparti.",
        ["Shots fired in a hurry go worse"] = "I colpi sparati di fretta vanno peggio",
        ["Shots fired close to the previous one go further from the group (Spearman {0}, the probability that it is chance is {1} %)."] = "I colpi sparati a poca distanza dal precedente vanno più lontano dal gruppo (Spearman {0}, probabilità che sia un caso {1} %).",
        ["After each shot put yourself back in position and check the wind again before firing the next."] = "Dopo ogni colpo rimettiti in posizione e ricontrolla il vento prima di sparare il successivo.",
        ["Regular pace ({0} s between one shot and the next on average), not linked to the errors."] = "Ritmo regolare (in media {0} s tra un colpo e l'altro), non legato agli errori.",
        ["The first shot of each series goes worse than the others"] = "Il primo colpo di ogni serie va peggio degli altri",
        ["The first shot of each series is on average {0} mm from the centre of its group, the others {1} mm (the probability that it is chance is {2} %)."] = "Il primo colpo di ogni serie sta in media a {0} mm dal centro del suo gruppo, gli altri a {1} mm (probabilità che sia un caso: {2} %).",
        ["Go over the position calmly before the first shot of each series; if you can, fire a settling shot first."] = "Ripassa la posizione con calma prima del primo colpo di ogni serie; se puoi, spara prima un colpo di assestamento.",
        ["The first shot of the series does not go worse than the others ({0} mm against {1} mm)."] = "Il primo colpo della serie non va peggio degli altri ({0} mm contro {1} mm).",
        ["The series have the same spread: constant concentration from the first series to the last."] = "Le serie hanno la stessa dispersione: concentrazione costante dalla prima all'ultima serie.",
        ["Concentration dropped in {0}"] = "Concentrazione calata in {0}",
        ["The spread is not the same in all the series (the probability that it is chance is {0} %): mean radius highest in {1} ({2} mm)."] = "La dispersione non è uguale in tutte le serie (probabilità che sia un caso: {0} %): raggio medio più alto in {1} ({2} mm).",
        ["Tiredness or hurry in that series: between series rest and start again from the complete routine."] = "Stanchezza o fretta in quella serie: tra le serie riposa e riparti dalla routine completa.",
        ["With the front rest only the rifle turns on the front support and the back is governed by you, so the sideways error comes mostly from behind. Check in this order: shoulder pressing in a different way from one shot to the next; cheek pushing the stock sideways; rear hand pulling or squeezing at the moment of the shot; rifle tilted in a different way every shot (easy without a rear rest: level on the scope); trigger pulled sideways. The wind comes after."] = "In mono appoggio il fucile ruota sull'appoggio anteriore e la parte posteriore la governi tu, quindi l'errore di lato viene soprattutto da dietro. Da controllare in quest'ordine: spalla che preme in modo diverso da un colpo all'altro; guancia che spinge il calcio di lato; mano posteriore che tira o stringe al momento dello sparo; fucile inclinato in modo diverso a ogni colpo (senza appoggio dietro succede facilmente: livella sull'ottica); grilletto tirato di lato. Il vento viene dopo.",
        ["With the front rest only the height is held by the rear hand: a different grip or support from one shot to the next, a shot fired at a different moment of the breath, a shoulder that pushes more or less, a front rest loaded in a different way."] = "In mono appoggio l'altezza la tiene la mano posteriore: stretta o sostegno diversi da un colpo all'altro, colpo partito in un momento diverso del respiro, spalla che spinge più o meno, appoggio anteriore caricato in modo diverso.",
        ["With the front rest only, a vertical spread smaller than the sideways one means the rear hand holds the height well: the work to do is on the side."] = "In mono appoggio un verticale più piccolo dell'orizzontale vuol dire che la mano posteriore tiene bene l'altezza: il lavoro da fare è sul lato.",
        ["With the rifle rested in front and behind, typical causes in this order: wind not read or not corrected; rear bag that moves or is squeezed sideways; cheek pressing on the stock in a different way; trigger pulled sideways; rifle tilted (level on the scope)."] = "Con il fucile appoggiato davanti e dietro, cause tipiche in quest'ordine: vento non letto o non corretto; sacchetto posteriore che si sposta o è schiacciato di lato; guancia che preme sul calcio in modo diverso; grilletto tirato di lato; fucile inclinato (livella sull'ottica).",
        ["With the double rest: rear bag squeezed in a different way; shoulder pushing more or less; shot fired at a different moment of the breath; recoil not always accompanied the same way."] = "Con il doppio appoggio: sacchetto posteriore schiacciato in modo diverso; spalla che spinge più o meno; colpo partito in un momento diverso del respiro; rinculo non accompagnato sempre allo stesso modo.",
        ["With the bipod: bipod loaded sideways (a different preload from one shot to the next); shoulder and cheek pushing sideways; rifle tilted (level on the scope); trigger pulled sideways; wind."] = "Con il bipiede: bipiede caricato di lato (precarico diverso da un colpo all'altro); spalla e guancia che spingono di lato; fucile inclinato (livella sull'ottica); grilletto tirato di lato; vento.",
        ["With the bipod: a different forward preload from one shot to the next, bipod that jumps at the recoil, rear hand or bag supporting in a different way, moment of the breath."] = "Con il bipiede: precarico in avanti diverso da un colpo all'altro, bipiede che salta al rinculo, mano o sacchetto posteriore che sostengono in modo diverso, momento del respiro.",
        ["Typical causes, to check in this order: wind not read or not corrected; rifle tilted (level on the scope); trigger pulled sideways (the finger must press straight back); cheek pressing on the stock in a different way from one shot to the next; tight grip. (Say how the rifle rests for more precise advice.)"] = "Cause tipiche, da controllare in quest'ordine: vento non letto o non corretto; fucile inclinato (livella sull'ottica); grilletto tirato di lato (il dito deve premere dritto all'indietro); guancia che preme sul calcio in modo diverso da un colpo all'altro; impugnatura stretta. (Indica come è appoggiato il fucile per consigli più precisi.)",
        ["Typical causes: shot fired at a different moment of the breath; rear support or hand holding in a different way; shoulder pushing more or less."] = "Cause tipiche: colpo partito in un momento diverso del respiro; appoggio posteriore o mano che sostengono in modo diverso; spalla che spinge più o meno.",
        ["up"] = "in alto",
        ["down"] = "in basso",
        ["and"] = "e",
        ["no click (too coarse)"] = "nessun click (troppo grossi)",
        ["{0} shots in {1} series at {2} m. Around the centre of each series the shots spread {3} mm sideways and {4} mm in height (SD), that is {5} and {6} MOA."] = "{0} colpi in {1} serie a {2} m. Attorno al centro di ogni serie i colpi si spargono {3} mm di lato e {4} mm in altezza (SD), cioè {5} e {6} MOA.",
        ["The longest spread runs {0}; it is {1} times the shortest."] = "La dispersione più lunga va {0}; è {1} volte la più corta.",
        ["Centre X (mm)"] = "Centro X (mm)",
        ["Centre Y (mm)"] = "Centro Y (mm)",
        ["SD X (mm)"] = "SD X (mm)",
        ["SD Y (mm)"] = "SD Y (mm)",
        ["Mean radius (mm)"] = "Raggio medio (mm)",
        ["The cartridges: each m/s more lifts the shot by {0} mm{1}. The velocity explains {2} % of the spread in height{3} The rest of the height and all the sideways spread come from the rifle, the shooter and the wind."] = "Le cartucce: ogni m/s in più alza il colpo di {0} mm{1}. La velocità spiega il {2} % della dispersione in altezza{3} Il resto dell'altezza e tutta la dispersione di lato vengono da fucile, tiratore e vento.",
        ["(theory at {0} m: about {1} mm)"] = "(teoria a {0} m: circa {1} mm)",
        ["(a sure figure)."] = "(dato sicuro).",
        ["(not a sure figure with these shots)."] = "(dato non sicuro con questi colpi).",
        ["Nothing in the pattern of these shots points to a mistake of the shooter. That is not proof that there is none: with few shots only large effects show."] = "Niente nella disposizione di questi colpi indica un errore del tiratore. Non è una prova che non ce ne siano: con pochi colpi si vedono solo gli effetti grandi.",
        ["What points to a mistake ({0}):"] = "Cosa indica un errore ({0}):",
        ["What was checked and is fine:"] = "Cosa è stato controllato ed è a posto:",
        ["Each reading is a test on these shots, with the probability that it is chance written beside it. A series of few shots (under 10) says little: a mistake that is not found may still be there, and one that is found should be confirmed on the next shooting."] = "Ogni lettura è un test su questi colpi, con accanto la probabilità che sia un caso. Una serie di pochi colpi (meno di 10) dice poco: un errore che non si trova può esserci lo stesso, e uno che si trova va confermato alla prossima sparata.",
        ["nearly sideways"] = "quasi di lato",
        ["nearly vertical"] = "quasi in verticale",
        ["slanting {0} ({1}°)"] = "in diagonale {0} ({1}°)",
        ["up to the right"] = "verso l'alto a destra",
        ["down to the right"] = "verso il basso a destra",
        ["Line {0}: expected two numbers (x and y in mm)."] = "Riga {0}: servono due numeri (x e y in mm).",
        ["Line {0}: the velocity or the time is not readable."] = "Riga {0}: la velocità o l'ora non si leggono.",
        ["{0}: {1} hits without a scale in mm were left out."] = "{0}: {1} colpi senza una scala in mm sono stati lasciati fuori.",
        ["The groups were shot at different distances: {0} m is used."] = "Le rosate sono state tirate a distanze diverse: si usano {0} m.",
        ["Group reading (shooter errors)"] = "Lettura della rosata (errori del tiratore)",
        ["Type the shots…"] = "Scrivi i colpi…",
        ["Read the shots"] = "Leggi i colpi",
        ["not known"] = "non noto",
        ["the coordinates are measured from the point of aim"] = "le coordinate sono misurate dal punto di mira",
        ["Distance (m):"] = "Distanza (m):",
        ["The rifle rests:"] = "Il fucile è appoggiato:",
        ["One click of the scope:"] = "Un click dell'ottica:",
        ["Nothing loaded yet: take groups from the archive or type the shots."] = "Ancora niente di caricato: prendi le rosate dall'archivio o scrivi i colpi.",
        ["The reading looks for the mistakes the shooter makes, from where the shots went: the zero of the sight, sideways against vertical spread, shots far from their group, the point of impact moving during the series, the time kept between shots, the first shot of each series, a group that gets worse from one series to the next. At least 5 shots are needed; with several series each series is centred on itself."] = "La lettura cerca gli errori del tiratore da dove sono andati i colpi: lo zero dell'ottica, la dispersione di lato contro quella verticale, i colpi lontani dal gruppo, il punto d'impatto che si sposta durante la serie, il tempo tenuto tra i colpi, il primo colpo di ogni serie, un gruppo che peggiora da una serie all'altra. Servono almeno 5 colpi; con più serie ogni serie è centrata su se stessa.",
        ["{0} groups of the archive, {1} shots."] = "{0} rosate dell'archivio, {1} colpi.",
        ["Type the shots"] = "Scrivi i colpi",
        ["One shot per line: x y in millimetres (x to the right, y UP), then, if you have them, the velocity in m/s and the time (10:14:02). A blank line starts a new series; a line that begins with # starts one and names it."] = "Un colpo per riga: x y in millimetri (x verso destra, y verso l'ALTO), poi, se li hai, la velocità in m/s e l'ora (10:14:02). Una riga vuota comincia una nuova serie; una riga che comincia con # ne comincia una e le dà il nome.",
        ["Typed: {0} shots in {1} series."] = "Scritti: {0} colpi in {1} serie.",
        ["At least {0} shots are needed to read them."] = "Servono almeno {0} colpi per leggerli.",
        ["not said"] = "non detto",
        ["front rest only"] = "solo appoggio davanti (mono)",
        ["front and rear rest"] = "appoggio davanti e dietro",
        ["bipod"] = "bipiede",
        ["🎯🔍  Group reading (shooter errors)"] = "🎯🔍  Lettura della rosata (errori del tiratore)",
        // LauncherForm
        ["PHASE 1 — PREPARATION"] = "FASE 1 — PREPARAZIONE",
        ["PHASE 2 — CHARGE LADDER"] = "FASE 2 — SCALA DI CARICHE",
        ["PHASE 3 — SEATING DEPTH"] = "FASE 3 — PROFONDITÀ DI SEDUTA",
        ["PHASE 4 — CHECK AT DISTANCE"] = "FASE 4 — VERIFICA A DISTANZA",
        ["PHASE 5 — FINAL LOAD, OVER TIME"] = "FASE 5 — CARICO FINALE, NEL TEMPO",
        ["PHASE 6 — TRAINING"] = "FASE 6 — ALLENAMENTO",
        ["Press \"Learn from the archive\": the measure that moves the velocity is drawn here."] = "Premi \"Impara dall'archivio\": qui viene disegnata la misura che muove la velocità.",
        ["What moves the velocity:"] = "Cosa muove la velocità:",
        ["less or more than the series average"] = "meno o più della media della serie",
        ["{0} shots in {1} series · link {2} · the model: {3} m/s per {4}"] = "{0} colpi in {1} serie · legame {2} · il modello: {3} m/s per {4}",
        ["unit"] = "unità",
        ["Compute the plan: the groups of cartridges are drawn here."] = "Calcola il piano: qui vengono disegnati i gruppi di cartucce.",
        ["The cartridges of each group, by expected velocity"] = "Le cartucce di ogni gruppo, per velocità attesa",
        ["m/s from the median cartridge"] = "m/s dalla cartuccia mediana",
        ["shot in random order: SD {0} m/s"] = "sparate in ordine casuale: SD {0} m/s",
        ["Enter the weights of 3 or more cases: their volumes are drawn here."] = "Scrivi i pesi di 3 o più bossoli: qui vengono disegnati i loro volumi.",
        ["Water held by each case"] = "Acqua contenuta in ogni bossolo",
        ["seat/jump numbers typed in"] = "numeri di seduta/salto scritti in",
        ["(dashed ring = mean radius)"] = "(cerchio tratteggiato = raggio medio)",
        ["tension typed in"] = "tensione scritta in",
        ["The ranking of the charges is drawn here once there are rounds logged at this distance."] = "La classifica delle cariche viene disegnata qui quando ci sono colpi registrati a questa distanza.",
        ["Score of each charge (out of 10)"] = "Punteggio di ogni carica (su 10)",
        ["Pick the strings of a session and compute the budget: where the SD comes from is drawn here."] = "Scegli le serie di una seduta e calcola il bilancio: qui viene disegnato da dove viene la SD.",
        ["Where the SD comes from"] = "Da dove viene la SD",
        ["The series: mean and one SD either side"] = "Le serie: media e una SD per lato",
        ["SD of all the shots {0} → inside the series {1} → what is left {2} m/s"] = "SD di tutti i colpi {0} → dentro le serie {1} → quello che resta {2} m/s",
        ["Press \"What the training taught\": the model before and after the latest session is drawn here."] = "Premi \"Cosa ha insegnato l'allenamento\": qui viene disegnato il modello prima e dopo l'ultima seduta.",
        ["What the session of {0} taught"] = "Cosa ha insegnato la seduta del {0}",
        ["SD left unexplained (m/s)"] = "SD rimasta inspiegata (m/s)",
        ["proven measures"] = "misure provate",
        ["leave-one-out link"] = "legame escludendo un colpo",
        ["SD expected of the match lot (m/s)"] = "SD attesa dal lotto di gara (m/s)",
        ["before"] = "prima",
        ["with"] = "con",
        ["before the session"] = "prima della seduta",
        ["with the session"] = "con la seduta",
        ["The shots of each string"] = "I colpi di ogni serie",
        ["Add the strings: their shots are drawn here, one column for each string."] = "Aggiungi le serie: i loro colpi vengono disegnati qui, una colonna per serie.",
        ["smallest SD: {0} ({1} {2})"] = "SD minima: {0} ({1} {2})",
        ["band = one standard deviation either side of the average"] = "banda = una deviazione standard per lato della media",
        ["average {0} {2} · SD {1} {2}"] = "media {0} {2} · SD {1} {2}",
        ["Copy picture"] = "Copia l'immagine",
        ["Save picture…"] = "Salva l'immagine…",
        ["The picture of the shots appears here once they are read."] = "L'immagine dei colpi compare qui appena sono letti.",
        ["centre of the shots"] = "centro dei colpi",
        ["centre of the shots (the aim is not known)"] = "centro dei colpi (la mira non è nota)",
        ["Where each shot went, from the aim of its own target"] = "Dove è andato ogni colpo, dalla mira del suo bersaglio",
        ["Where the shots went, from the aim"] = "Dove sono andati i colpi, dalla mira",
        ["normal"] = "normale",
        ["Charge weights ({0}, comma-separated, optional)"] = "Pesi delle cariche ({0}, separati da virgola, facoltativo)",
        ["Distance ({0}, optional)"] = "Distanza ({0}, facoltativa)",
        ["Unit of the weights:"] = "Unità dei pesi:",
        ["Unit of the distance:"] = "Unità della distanza:",
        ["📏  Units of measure (grains/grams, mm/inches, m/yards, MOA/mrad)"] = "📏  Unità di misura (grani/grammi, mm/pollici, m/iarde, MOA/mrad)",
        ["Units of measure"] = "Unità di misura",
        ["Choose the unit each kind of number is shown and typed in. The archive keeps its own units whatever you choose here (grains, millimetres, metres, MOA): nothing stored changes."] = "Scegli l'unità in cui ogni tipo di numero viene mostrato e scritto. L'archivio tiene le sue unità qualunque cosa scelga qui (grani, millimetri, metri, MOA): niente di ciò che è salvato cambia.",
        ["Weights (cases, bullets, primers, powder charges)"] = "Pesi (bossoli, proiettili, inneschi, cariche di polvere)",
        ["Lengths (case, bullet, cartridge, neck, position of the shots on the target)"] = "Lunghezze (bossolo, proiettile, cartuccia, colletto, posizione dei colpi sul bersaglio)",
        ["Distances (shooting distance)"] = "Distanze (distanza di tiro)",
        ["Angles (errors on the target, the zero, the clicks)"] = "Angoli (errori sul bersaglio, lo zero, i click)",
