        ["milliradians (mrad)"] = "milliradianti (mrad)",
        ["Click of the scope"] = "Click dell'ottica",
        ["MOA: 1/8, 1/4, 1/2. Milliradians: 1/20, 1/10. The readings of the shots use it to say how many clicks to give."] = "MOA: 1/8, 1/4, 1/2. Milliradianti: 1/20, 1/10. Le letture dei colpi lo usano per dire quanti click dare.",
        ["Every field back to the starting unit"] = "Ogni campo torna all'unità di partenza",
        ["No field has a unit of its own."] = "Nessun campo ha un'unità propria.",
        ["Fields with a unit of their own ({0}): {1}"] = "Campi con un'unità propria ({0}): {1}",
        ["A column or a field can have its own unit: right-click the title of a column in the tables of the cartridges, or use the unit box beside the distance and the coordinates in the readings of the shots."] = "Una colonna o un campo può avere un'unità propria: clic destro sul titolo di una colonna nelle tabelle delle cartucce, oppure usa la casella dell'unità accanto alla distanza e alle coordinate nelle letture dei colpi.",
        ["Distance ({0}):"] = "Distanza ({0}):",
